package com.yeyamo_mobile.api.culture_service.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="culture_challenges") public class CultureChallenge{public enum Type{SPEAK_LANGUAGE,ASK_AN_ELDER,NAME_MEANING,PRESENT_TRADITION,FAMILY_STORY,ORAL_HISTORY,CUSTOM}public enum Status{DRAFT,SCHEDULED,ACTIVE,PAUSED,COMPLETED,CANCELLED}@Id private UUID id;@Column(nullable=false)private String title;@Column(nullable=false,columnDefinition="TEXT")private String description;@Enumerated(EnumType.STRING)@Column(nullable=false)private Type type;@Column(name="country_code",length=2)private String countryCode;@Column(name="language_code",length=35)private String languageCode;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(name="reward_definition_id")private UUID rewardDefinitionId;@Column(name="moderation_required",nullable=false)private boolean moderationRequired;@Column(name="created_by",nullable=false)private String createdBy;protected CultureChallenge(){}public boolean available(Instant now){return status==Status.ACTIVE&&!now.isBefore(startsAt)&&now.isBefore(endsAt);}public UUID getId(){return id;}public String getTitle(){return title;}public String getDescription(){return description;}public Type getType(){return type;}public String getCountryCode(){return countryCode;}public String getLanguageCode(){return languageCode;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public Status getStatus(){return status;}public UUID getRewardDefinitionId(){return rewardDefinitionId;}public boolean isModerationRequired(){return moderationRequired;}}
